sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.leave-balance-wrapper {
    padding: 25px;
}

.leave-balance-wrapper h2 {
    text-align: center;
    margin-bottom: 5px;
}

.subtitle {
    text-align: center;
    margin-bottom: 25px;
    color: #666;
}

.balance-grid {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 20px;
}

.balance-card {
    width: 210px;
    min-height: 190px;
    padding: 20px;
    border-radius: 14px;
    text-align: center;
    background: #ffffff;
    box-shadow: 0 4px 14px rgba(0,0,0,.12);
}

.icon {
    font-size: 42px;
}

.balance-card h3 {
    font-size: 20px;
    margin: 12px 0;
}

.count {
    font-size: 34px;
    font-weight: bold;
}

.balance-card p {
    color: #666;
}

sp_widget.script:
(function() {

    data.found = false;
    data.balance = {};

    var gr = new GlideRecord('x_snc_unified_hr_0_leave_balance');
    gr.addQuery('employee', gs.getUserID());
    gr.setLimit(1);
    gr.query();

    if (gr.next()) {

        data.found = true;

        data.balance.casual =
            gr.getValue('casual_leave_balance') || 0;

        data.balance.sick =
            gr.getValue('sick_leave_balance') || 0;

        data.balance.earned =
            gr.getValue('earned_leave_balance') || 0;

        data.balance.paternity =
            gr.getValue('paternity_leave_balance') || 0;

        data.balance.maternity =
            gr.getValue('maternity_leave_balance') || 0;
    }

})();
